import { Injector, InjectionToken, inject, runInInjectionContext } from '@angular/core';

// Un «contrato»: qué necesita el código de afuera
const RELOJ = new InjectionToken('RELOJ');

class RelojReal { ahora() { return new Date(); } }
class RelojFijo { ahora() { return new Date('2026-11-13T09:00:00-03:00'); } }

// Esta clase NO crea su reloj: lo pide con inject()
class Etiquetadora {
  reloj = inject(RELOJ);
  etiqueta(id) {
    const h = this.reloj.ahora().toLocaleTimeString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', hour12: false });
    return `Bulto ${id} despachado ${h}`;
  }
}

const produccion = Injector.create({ providers: [{ provide: RELOJ, useClass: RelojReal }] });
const prueba = Injector.create({ providers: [{ provide: RELOJ, useClass: RelojFijo }] });

console.log('producción:', runInInjectionContext(produccion, () => new Etiquetadora()).etiqueta(42));
console.log('prueba    :', runInInjectionContext(prueba, () => new Etiquetadora()).etiqueta(42));
console.log('prueba    :', runInInjectionContext(prueba, () => new Etiquetadora()).etiqueta(43));

try { new Etiquetadora(); } catch (e) { console.log('fuera de contexto:', e.message.split('\n')[0].slice(0, 120)); }

// Singleton: el mismo injector entrega la misma instancia
const r1 = prueba.get(RELOJ), r2 = prueba.get(RELOJ);
console.log('misma instancia en el mismo injector:', r1 === r2);

class Contenedor {
  constructor(padre = null) {
    this.fabricas = new Map();
    this.instancias = new Map();
    this.padre = padre;
  }
  proveer(token, fabrica) { this.fabricas.set(token, fabrica); }
  pedir(token) {
    if (this.instancias.has(token)) return this.instancias.get(token);
    if (this.fabricas.has(token)) {
      const valor = this.fabricas.get(token)(this);
      this.instancias.set(token, valor);
      return valor;
    }
    if (this.padre) return this.padre.pedir(token);
    throw new Error(`No hay proveedor para ${String(token)}`);
  }
}

const RELOJ = Symbol('RELOJ');
const ETIQUETADORA = Symbol('ETIQUETADORA');

const raiz = new Contenedor();
raiz.proveer(RELOJ, () => ({ ahora: () => '15:16' }));
raiz.proveer(ETIQUETADORA, (c) => {
  const reloj = c.pedir(RELOJ); // la clase pide lo que necesita, no lo fabrica
  return { etiqueta: (id) => `Bulto ${id} despachado ${reloj.ahora()}` };
});

const prueba = new Contenedor(raiz); // un contenedor hijo
prueba.proveer(RELOJ, () => ({ ahora: () => '09:00' }));
prueba.proveer(ETIQUETADORA, raiz.fabricas.get(ETIQUETADORA)); // misma receta, otro reloj

console.log(raiz.pedir(ETIQUETADORA).etiqueta(42));
console.log(prueba.pedir(ETIQUETADORA).etiqueta(42));
console.log('mismo objeto al pedir dos veces:', raiz.pedir(RELOJ) === raiz.pedir(RELOJ));
try { new Contenedor().pedir(RELOJ); } catch (e) { console.log('Error:', e.message); }

@Service()
export class Pedidos {
  private http = inject(HttpClient);

  buscar(texto: string): Observable<Pedido[]> {
    return this.http.get<Pedido[]>('http://127.0.0.1:18629/pedidos', { params: { q: texto } });
  }
}

// Un «Observable» de juguete: una función que recibe a quien escucha
function crearFlujo(receta) {
  return {
    subscribe(escucha) {
      return receta(escucha); // cada suscripción ejecuta la receta de nuevo
    },
    pipe(...operadores) {
      return operadores.reduce((flujo, op) => op(flujo), this);
    },
  };
}
const map = (f) => (flujo) =>
  crearFlujo((escucha) => flujo.subscribe((v) => escucha(f(v))));
const filter = (f) => (flujo) =>
  crearFlujo((escucha) => flujo.subscribe((v) => f(v) && escucha(v)));

// La receta: emite tres bultos escaneados en un depósito
const escaneos = crearFlujo((escucha) => {
  console.log('(arranca el escáner)');
  const bultos = [{ id: 7, kg: 12 }, { id: 8, kg: 31 }, { id: 9, kg: 4 }];
  bultos.forEach((b, i) => setTimeout(() => escucha(b), i * 50));
});

const pesados = escaneos.pipe(
  filter((b) => b.kg > 10),
  map((b) => `Bulto ${b.id}: ${b.kg} kg, va al sector de carga pesada`),
);

console.log('Armé el flujo, todavía no pasó nada.');
pesados.subscribe((msg) => console.log(msg));
await new Promise((r) => setTimeout(r, 200));
console.log('--- segunda suscripción ---');
pesados.subscribe((msg) => console.log('otro:', msg));
await new Promise((r) => setTimeout(r, 200));

import { Observable, Subject, debounceTime, switchMap } from 'rxjs';

const t0 = Date.now();
const ms = () => String(Date.now() - t0).padStart(4);
const dormir = (n) => new Promise((r) => setTimeout(r, n));

const buscar = (q) => new Observable((s) => {
  console.log(`${ms()} ms  sale la búsqueda de «${q}»`);
  let completa = false;
  const id = setTimeout(() => { completa = true; s.next(`resultados de «${q}»`); s.complete(); }, 300);
  return () => { clearTimeout(id); if (!completa) console.log(`${ms()} ms  la búsqueda de «${q}» se CANCELA`); };
});

const teclas = new Subject();
teclas.pipe(debounceTime(100), switchMap(buscar)).subscribe((r) => console.log(`${ms()} ms  llega: ${r}`));

const tecla = (t) => { console.log(`${ms()} ms  tecla -> «${t}»`); teclas.next(t); };
tecla('f'); await dormir(40);
tecla('fe'); await dormir(40);
tecla('fer'); await dormir(170);   // pausa de 170 ms: sale la búsqueda de «fer»
tecla('ferr'); await dormir(600);  // escribe mientras «fer» sigue en vuelo
